-- ============================================
-- 补充景点详情内容 (detail_content)
-- ============================================

USE `ningbo_tourism`;

-- 四明山森林公园 (id=4)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>四明山国家森林公园地处四明山腹地，平均海拔700米，森林覆盖率高达96%。公园总面积6665公顷，是浙东地区规模最大的森林公园，也是宁波市重要的生态旅游目的地。</p><h2>主要看点</h2><ul><li><strong>仰天湖</strong>：四明山主峰之一，海拔810米，高山湖泊宛如天镜</li><li><strong>鹁鸪岩洞</strong>：天然溶洞，洞内钟乳石千姿百态</li><li><strong>深秀谷</strong>：峡谷幽深，溪水潺潺，是避暑纳凉的绝佳去处</li><li><strong>红枫古道</strong>：秋季漫山红叶，被誉为"浙东最美红枫之路"</li><li><strong>商量岗滑雪场</strong>：冬季滑雪胜地，是华东地区少有的天然雪场</li></ul><h2>四季看点</h2><p>春赏杜鹃映山红，夏避酷暑享清凉，秋观层林尽染红叶，冬赏雾凇玩滑雪。四季景色各异，尤以秋季红叶和冬季雾凇最为壮观。</p><h2>实用信息</h2><p>建议游览时间：半天至一天。自驾前往最为方便，山路弯曲需注意安全。山上气温比市区低5-8℃，建议多带衣物。</p>' WHERE id = 4;

-- 保国寺 (id=5)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>保国寺位于宁波市江北区洪塘镇的灵山之麓，始建于东汉光武帝时期，是全国重点文物保护单位。寺内大殿建于北宋大中祥符六年（1013年），是江南现存最古老、保存最完整的木结构建筑，被誉为"中国古建筑的活化石"。</p><h2>主要看点</h2><ul><li><strong>大雄宝殿</strong>：北宋原构建筑，距今逾千年，以独特的"虫不蛀、鸟不栖、蜘蛛不结网、灰尘不上梁"四绝闻名</li><li><strong>藏经楼</strong>：收藏大量佛教典籍和历史文献</li><li><strong>天王殿</strong>：清代重建，气势庄严</li><li><strong>灵山景区</strong>：古寺周围林木葱郁，环境清幽，是徒步登山的好去处</li></ul><h2>建筑奇迹</h2><p>大殿采用了独特的抬梁式结构，不用一颗钉子，全靠榫卯连接。殿内木材经千年仍不朽，据研究是因采用了黄桧木材并巧妙利用了气流原理。这一建筑智慧令中外建筑学者叹为观止。</p><h2>实用信息</h2><p>门票免费，建议游览时间1-2小时。从宁波市区乘坐公交332路可直达。</p>' WHERE id = 5;

-- 老外滩 (id=6)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>宁波老外滩坐落于三江口（甬江、奉化江和余姚江交汇处）的北岸，是中国最早的外滩，比上海外滩早20年开埠（1844年）。现已发展成为集餐饮、酒吧、文化、休闲于一体的时尚街区。</p><h2>主要看点</h2><ul><li><strong>欧式建筑群</strong>：保留了大量1920-1930年代的哥特式和巴洛克式建筑</li><li><strong>天主教堂</strong>：哥特式建筑风格的江北天主教堂，是宁波的标志性建筑之一</li><li><strong>三江口夜景</strong>：夜晚灯火辉煌，是宁波夜游的首选之地</li><li><strong>特色酒吧街</strong>：聚集众多风格各异的酒吧和西餐厅</li><li><strong>老外滩城市展览馆</strong>：展示宁波外滩百年变迁的历史</li></ul><h2>美食推荐</h2><p>老外滩汇集了中西餐饮，既有正宗宁波菜馆，也有意大利餐厅、日料、咖啡馆等。夏季可在露天酒吧享受江风习习的惬意时光。</p><h2>实用信息</h2><p>全天免费开放。地铁2号线外滩大桥站下车步行5分钟。夜景最佳观赏时间为19:00-22:00。</p>' WHERE id = 6;

-- 河姆渡遗址 (id=7)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>河姆渡遗址位于余姚市河姆渡镇，距今约7000年，是中国新石器时代最重要的考古发现之一。遗址出土了大量稻作遗存，证明了长江流域是世界稻作文明的发源地，被列为全国重点文物保护单位。</p><h2>主要看点</h2><ul><li><strong>遗址博物馆</strong>：展示出土文物6700余件，包括陶器、骨器、石器等</li><li><strong>干栏式建筑复原</strong>：展示7000年前先民的居住方式，被称为"世界第一栋房子"</li><li><strong>稻作文化展</strong>：展示世界上最早的人工栽培水稻遗存</li><li><strong>原始生活场景复原</strong>：生动再现河姆渡先民的日常生活</li><li><strong>"双鸟朝阳"象牙雕</strong>：国家一级文物，河姆渡文化的标志性器物</li></ul><h2>文化意义</h2><p>河姆渡遗址的发现改写了中国文明史，证明了长江流域同样是中华文明的摇篮。遗址中发现的人工栽培稻谷将中国稻作历史提前至7000年前。</p><h2>实用信息</h2><p>门票免费。从宁波市区乘坐公交可达余姚后转车。建议游览时间2-3小时。</p>' WHERE id = 7;

-- 渔山列岛 (id=8)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>渔山列岛位于宁波市象山县石浦镇东南约27海里处，由54个岛礁组成，被誉为"亚洲第一钓场"。这里海水清澈见底，礁石奇特多姿，是潜水、垂钓和观日出的绝佳海岛。</p><h2>主要看点</h2><ul><li><strong>北渔山灯塔</strong>：始建于1895年的百年灯塔，是渔山列岛的标志</li><li><strong>仙人桥</strong>：天然岩石拱桥，横跨于碧海之上，景色壮观</li><li><strong>五虎礁</strong>：五块巨石如五虎蹲踞，是海钓的绝佳钓位</li><li><strong>日出观赏</strong>：渔山列岛是浙江沿海看日出最早的地方</li><li><strong>潜水天堂</strong>：水质清澈，能见度高，海底珊瑚和热带鱼群丰富</li></ul><h2>活动推荐</h2><p>海钓是渔山列岛最受欢迎的活动，可钓到鲈鱼、黑鲷、真鲷等。夜钓更是别有一番趣味。夏季还可以浮潜，欣赏丰富的海底生态。</p><h2>实用信息</h2><p>从石浦码头乘快艇约1.5小时到达。建议至少安排2天1夜行程。最佳季节5-10月，需避开台风季节。岛上食宿条件有限，建议提前预订。</p>' WHERE id = 8;

-- 浙东抗日根据地旧址 (id=9)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>浙东抗日根据地旧址群位于余姚市梁弄镇，是全国重点文物保护单位和全国百个红色旅游经典景区之一。这里是抗日战争时期浙东地区的革命中心，见证了浙东军民英勇抗战的光辉历程。</p><h2>主要看点</h2><ul><li><strong>中共浙东区委旧址</strong>：位于梁弄镇横坎头村，是浙东革命的指挥中心</li><li><strong>浙东行政公署旧址</strong>：浙东抗日民主政权所在地</li><li><strong>浙东银行旧址</strong>：抗战时期发行抗币的金融机构</li><li><strong>新四军浙东游击纵队司令部旧址</strong>：何克希、谭启龙等革命先辈在此指挥作战</li><li><strong>浙东抗日军政干校旧址</strong>：培养抗日骨干力量的摇篮</li></ul><h2>红色教育</h2><p>梁弄镇被誉为"浙东小延安"，是浙江省重要的爱国主义教育基地。每年有大量党政机关和学校组织前来开展红色教育活动。</p><h2>实用信息</h2><p>门票免费。从宁波市区驾车约1.5小时。建议与四明山景区联游，安排一天行程。</p>' WHERE id = 9;

-- 四明山革命烈士纪念碑 (id=10)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>四明山革命烈士纪念碑矗立于余姚市四明山主峰之上，碑高18.5米，是纪念在浙东革命斗争中英勇牺牲的革命先烈而建。纪念碑周围松柏苍翠，环境庄严肃穆，是浙江省重要的烈士纪念设施。</p><h2>主要看点</h2><ul><li><strong>烈士纪念碑</strong>：碑身高耸，正面镌刻"革命烈士永垂不朽"八个大字</li><li><strong>烈士纪念馆</strong>：陈列浙东革命历史资料和烈士遗物</li><li><strong>四明山主峰</strong>：海拔979米，登顶可俯瞰四明群山</li><li><strong>英烈墙</strong>：镌刻着2000余位革命烈士的名字</li></ul><h2>历史背景</h2><p>四明山是浙东革命的重要根据地。从土地革命时期到解放战争，无数革命先烈在此浴血奋战。纪念碑的建立，是为了铭记这段波澜壮阔的革命历史。</p><h2>实用信息</h2><p>门票免费。位于四明山深处，自驾前往较为方便。可与四明山森林公园、浙东抗日根据地旧址联游。</p>' WHERE id = 10;

-- 天一阁·月湖景区 (id=11)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>天一阁·月湖景区是国家5A级旅游景区，由天一阁博物院和月湖公园两大核心区域组成。月湖开凿于唐贞观年间（636年），因湖面呈月形而得名，是宁波城市的发源地和文化核心区。</p><h2>主要看点</h2><ul><li><strong>月湖十洲</strong>：湖中有十个小洲，分布着众多古迹和园林</li><li><strong>贺秘监祠</strong>：纪念唐代大诗人贺知章的祠堂</li><li><strong>水则碑</strong>：中国现存最早的水利测量标尺，距今700余年</li><li><strong>银台第官宅</strong>：保存完好的明代官宅建筑群</li><li><strong>月湖美术馆</strong>：展示当代艺术作品的文化空间</li><li><strong>湖心寺</strong>：始建于唐代的古刹遗址</li></ul><h2>文化底蕴</h2><p>月湖周边遗迹密布千年，历史上曾是宁波城市的政治、经济、文化中心。湖畔曾聚居着众多文人雅士，留下了丰富的文化遗产。如今的月湖景区融合了历史文化与城市休闲，是市民和游客散步休憩的好去处。</p><h2>实用信息</h2><p>月湖公园免费开放，天一阁门票30元。地铁1号线西门口站下车步行约10分钟。建议游览时间3-4小时。</p>' WHERE id = 11;

-- 松兰山滨海旅游度假区 (id=12)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>松兰山滨海旅游度假区位于象山县东部海滨，拥有长达2公里的优质沙滩，是宁波最受欢迎的海滨度假目的地。这里海水清澈、沙质细软，被评为浙江省亲子景点榜前15名。</p><h2>主要看点</h2><ul><li><strong>金沙滩</strong>：长约600米的主沙滩，沙质细腻，适合游泳和日光浴</li><li><strong>银沙滩</strong>：较为安静的沙滩，适合赶海拾贝</li><li><strong>海上运动</strong>：提供帆船、摩托艇、香蕉船等水上娱乐项目</li><li><strong>滨海栈道</strong>：沿海修建的步道，可欣赏壮丽的海岸线风光</li><li><strong>日出观景台</strong>：面朝东海，是看日出的绝佳位置</li></ul><h2>亲子活动</h2><p>沙滩挖沙、堆沙堡是孩子们的最爱。度假区内还设有儿童乐园、沙滩排球场等设施。退潮时可以在礁石间赶海，抓小螃蟹和海螺。</p><h2>实用信息</h2><p>免费开放（部分项目收费）。从宁波市区自驾约1.5小时。最佳季节6-9月。建议携带防晒用品和换洗衣物。</p>' WHERE id = 12;

-- 溪口-滕头旅游景区 (id=13)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>溪口-滕头旅游景区是国家5A级旅游景区，位于宁波奉化区。景区由溪口镇和滕头村两大核心区域组成。溪口是蒋介石的故乡，拥有丰富的近代人文资源；滕头村则是全球生态500佳和世博会唯一入选乡村案例。</p><h2>溪口景区看点</h2><ul><li><strong>蒋氏故居</strong>：蒋介石出生地丰镐房，展示蒋氏家族百年历史</li><li><strong>雪窦山</strong>：海拔800米，千丈岩瀑布落差186米，气势磅礴</li><li><strong>雪窦寺</strong>：弥勒佛道场，中国五大佛教名山之一</li><li><strong>妙高台</strong>：蒋介石别墅所在地，登顶可俯瞰千丈岩全景</li><li><strong>千丈岩飞瀑</strong>：王安石曾赋诗"拔地万重青嶂立，悬空千丈素流分"</li></ul><h2>滕头村看点</h2><ul><li><strong>生态农业</strong>：展示现代农业科技和绿色生态理念</li><li><strong>乡村体验</strong>：可参与农耕、采摘等乡村活动</li></ul><h2>实用信息</h2><p>联票210元。从宁波市区乘坐班车约1小时到溪口。建议安排一整天游览。雪窦山有索道和观光车可代步。</p>' WHERE id = 13;

-- 象山影视城 (id=14)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>象山影视城是国家4A级旅游景区，位于象山县新桥镇大塘港区域。这里是《琅琊榜》《芈月传》《三生三世十里桃花》《长安十二时辰》等百余部热门影视剧的拍摄地，被誉为"东方好莱坞"。</p><h2>主要看点</h2><ul><li><strong>神雕侠侣城</strong>：复原南宋时期建筑风貌，是最早建成的拍摄区域</li><li><strong>春秋战国城</strong>：气势恢宏的先秦建筑群，《芈月传》主要取景地</li><li><strong>民国城</strong>：再现1920-1940年代的上海滩风貌</li><li><strong>唐城</strong>：大唐盛世建筑群，《长安十二时辰》拍摄地</li><li><strong>琅琊阁</strong>：《琅琊榜》经典场景复原，粉丝打卡圣地</li></ul><h2>互动体验</h2><p>景区内定时上演武打特技秀、古装情景剧等表演。游客可租借古装拍照，体验穿越的乐趣。节假日还有大型实景演出。</p><h2>实用信息</h2><p>门票150元。从宁波市区自驾约1.5小时。建议游览时间4-5小时。注意查看演出时间表，合理安排游览路线。</p>' WHERE id = 14;

-- 罗蒙环球乐园 (id=15)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>罗蒙环球乐园位于宁波南部商务区，是一座大型室内主题乐园，总投资超过30亿元。乐园以"环球旅行"为主题，设有多个主题区域，是浙江省亲子景点榜排名前20的热门乐园。</p><h2>主要区域</h2><ul><li><strong>欧洲区</strong>：哥特式城堡和过山车，刺激指数五颗星</li><li><strong>美洲区</strong>：西部牛仔风情，有室内漂流和矿山车</li><li><strong>亚洲区</strong>：东方文化主题，适合亲子互动体验</li><li><strong>梦幻世界</strong>：专为儿童设计的区域，有旋转木马和童话城堡</li><li><strong>4D影院</strong>：身临其境的沉浸式观影体验</li></ul><h2>游玩建议</h2><p>乐园为室内场馆，不受天气影响。工作日人较少，体验更佳。身高1.2米以下儿童需成人陪同。乐园内有多个餐饮点，也可自带食物。</p><h2>实用信息</h2><p>门票约160元起。地铁1号线鄞州客运总站下车步行约15分钟。营业时间10:00-17:00（节假日延长）。建议游玩时间4-6小时。</p>' WHERE id = 15;

-- 鸣鹤古镇 (id=16)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>鸣鹤古镇位于慈溪市观海卫镇，始建于唐开元年间，距今已有1200多年历史。古镇依白洋湖而建，三面环山，是浙东地区保存最完整的古镇之一。因其独特的药材商帮文化而闻名，历史上曾是国药业的重要发源地之一。</p><h2>主要看点</h2><ul><li><strong>药材商帮古宅</strong>：保留了多处清代药材商人的豪宅大院</li><li><strong>银号弄</strong>：古镇最具特色的老街巷，青石板路两旁商铺林立</li><li><strong>国医馆旧址</strong>：见证古镇药商文化的辉煌历史</li><li><strong>沈氏宗祠</strong>：气势宏伟的清代宗族建筑</li><li><strong>白洋湖</strong>：古镇旁的天然湖泊，湖光山色相映成趣</li></ul><h2>特色美食</h2><p>古镇特产年糕饺、梅花糕、臭豆腐等传统小吃。每逢节假日，老街上各种传统小吃摊位热闹非凡。</p><h2>实用信息</h2><p>免费开放。从宁波市区驾车约40分钟。建议游览时间半天。工作日前往游客较少，更能感受古镇的宁静韵味。</p>' WHERE id = 16;

-- 前童古镇 (id=17)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>前童古镇位于宁海县城西南14公里处，始建于宋末元初，至今已有760多年历史。古镇以童姓族人聚居而得名，是一座保存完好的江南水乡古镇，曾获"浙江省历史文化名镇"称号。陈逸飞执导的电影《理发师》即在此取景。</p><h2>主要看点</h2><ul><li><strong>明清古建筑群</strong>：保存着大量明清时期的四合院和祠堂</li><li><strong>职思其居</strong>：前童古镇最精美的古宅，木雕精湛</li><li><strong>民俗博物馆</strong>：展示浙东地区传统民俗文化</li><li><strong>石镜山</strong>：古镇后山，登顶可俯瞰古镇全貌</li><li><strong>八卦水系</strong>：古镇独特的水利灌溉系统，按八卦方位布局</li></ul><h2>民俗活动</h2><p>元宵节期间的"行会"活动是前童古镇最盛大的传统民俗，鼓亭、抬阁、秋千等表演热闹非凡，被列入国家级非物质文化遗产名录。</p><h2>实用信息</h2><p>门票约40元。从宁波市区驾车约1.5小时。建议游览时间半天。前童豆腐和前童三宝（空心腐、香干、豆腐皮）是当地特色美食。</p>' WHERE id = 17;

-- 浙东小九寨 (id=18)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>浙东小九寨位于余姚市大岚镇柿林村附近的白岩溪流域，因其秀美的山水风光酷似四川九寨沟而得名。景区以清澈碧绿的溪水、层叠的瀑布群和原始的自然生态著称，是宁波周边徒步爱好者的热门目的地。</p><h2>主要看点</h2><ul><li><strong>翡翠潭</strong>：水色碧绿如翡翠，是景区最著名的景点</li><li><strong>瀑布群</strong>：沿溪分布着大小十余处瀑布，最大落差约30米</li><li><strong>峡谷栈道</strong>：沿峡谷修建的木栈道，两侧树木葱茏</li><li><strong>古村柿林</strong>：拥有百年柿树的古朴村落，秋季柿子挂满枝头</li><li><strong>丹山赤水</strong>：赤色丹霞地貌与碧水交映的奇特景观</li></ul><h2>徒步路线</h2><p>主要徒步路线全程约4公里，沿白岩溪上行，经过多处潭瀑，终点为柿林古村。全程约需2-3小时，难度适中，适合大部分游客。</p><h2>实用信息</h2><p>门票约50元。从宁波市区驾车约1.5小时。最佳季节4-10月。溪谷湿滑，建议穿防滑鞋。夏季是避暑戏水的好去处。</p>' WHERE id = 18;

-- 宁波博物馆 (id=19)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>宁波博物馆位于鄞州区首南中路1000号，由普利兹克建筑奖获得者、中国建筑大师王澍设计。博物馆建筑本身就是一件艺术品，大量使用了宁波老城拆迁回收的旧砖瓦，将历史记忆融入现代建筑之中，荣获中国建筑最高奖鲁班奖。</p><h2>主要看点</h2><ul><li><strong>"东方神舟"展厅</strong>：展示宁波7000年文明史，从河姆渡文化到现代港城</li><li><strong>"阿拉老宁波"展厅</strong>：复原旧时宁波城市场景，展示近代市井生活</li><li><strong>竹编馆</strong>：展示宁波精湛的竹编工艺和民间手工艺品</li><li><strong>临时展厅</strong>：定期举办国内外高水平艺术和文物展览</li><li><strong>建筑本体</strong>：独特的"瓦爿墙"和竹条模板混凝土外墙值得细细品味</li></ul><h2>建筑特色</h2><p>王澍在设计中大量使用了从宁波旧城拆除中回收的数百万块旧砖瓦，将城市的历史记忆嵌入建筑肌理。建筑外观如同一座由历史碎片堆砌的山丘，与周围环境和谐共生。</p><h2>实用信息</h2><p>免费参观（需预约）。地铁3号线儿童公园站下车步行约10分钟。周一闭馆。建议游览时间2-3小时。</p>' WHERE id = 19;

-- 中国港口博物馆 (id=20)
UPDATE `spots` SET `detail_content` = '<h2>景点简介</h2><p>中国港口博物馆位于北仑区春晓街道，是国内首个以港口为主题的大型专题博物馆，也是国家一级博物馆。博物馆全面展示了中国港口的发展历程和宁波舟山港作为世界第一大港的辉煌成就。</p><h2>主要看点</h2><ul><li><strong>"港通天下"基本陈列</strong>：展示中国港口从古至今的发展历程</li><li><strong>"创新之路"展厅</strong>：介绍现代港口的科技创新和智能化建设</li><li><strong>古船模型</strong>：展示各朝代航海船舶的精美模型</li><li><strong>海上丝绸之路展</strong>：展示宁波在海上丝绸之路中的重要地位</li><li><strong>港口模拟驾驶</strong>：互动体验区，可模拟操控集装箱起重机</li><li><strong>水下考古展</strong>：展示宁波近海水下考古发现</li></ul><h2>教育意义</h2><p>宁波舟山港是全球货物吞吐量第一大港，博物馆生动展示了港口与城市、港口与世界的紧密联系，是了解海洋文化和港口历史的最佳课堂。</p><h2>实用信息</h2><p>免费参观。从宁波市区驾车约40分钟。建议游览时间2-3小时。周一闭馆。</p>' WHERE id = 20;

